function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 30) return 'nums needs 1 to 30 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 10000)) return 'Each value is an integer from 0 to 10000.';
  return null;
}

