function splitArraySameAverage(nums) {
  const n = nums.length;
  const total = nums.reduce((sum, num) => sum + num, 0);
  const sizes = new Int32Array(total + 1);
  sizes[0] = 1;

  for (const num of nums) {
    for (let s = total; s >= num; s--) {
      sizes[s] |= sizes[s - num] << 1;
    }
  }

  for (let k = 1; k <= Math.floor(n / 2); k++) {
    if ((total * k) % n !== 0) {
      continue;
    }
    const target = (total * k) / n;
    if ((sizes[target] >> k) & 1) {
      return true;
    }
  }
  return false;
}

