function splitArraySameAverage(nums) {
  const n = nums.length;
  let total = 0;
  const counts = new Map();
  for (const v of nums) { total += v; counts.set(v, (counts.get(v) || 0) + 1); }
  const values = [...counts.keys()];
  // Choose how many copies of each distinct value go into A; equal values are interchangeable.
  const search = (i, size, part) => {
    if (i === values.length) return size > 0 && size < n && part * n === total * size;
    for (let take = 0; take <= counts.get(values[i]); take++) {
      if (search(i + 1, size + take, part + take * values[i])) return true;
    }
    return false;
  };
  return search(0, 0, 0);
}

