function generate(rand, size) {
  const pick = (max) => Math.floor(rand() * (max + 1));
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 12);
    const max = [3, 10, 30][Math.floor(rand() * 3)];
    return [Array.from({ length: n }, () => pick(max))];
  }
  const n = 25 + Math.floor(rand() * 6);
  const mode = Math.floor(rand() * 3);
  if (mode === 0) return [Array.from({ length: n }, () => pick(10000))];
  if (mode === 1) {
    // Values spread far apart: equal averages are rare.
    const nums = Array.from({ length: n }, (_, i) => Math.min(10000, 1 + i * 37 + pick(30)));
    nums[0] = 10000 - pick(50);
    return [nums];
  }
  // Most values equal with a few outliers.
  const base = pick(10000);
  return [Array.from({ length: n }, () => (rand() < 0.15 ? pick(10000) : base))];
}
